const contacts = document.querySelector(".contacts");
const form = document.querySelector(".form");
const containerElem = document.querySelector(".container")

const inputs = {
  nameInput: document.querySelector("input[id='name']"),
  surnameInput: document.querySelector("input[id='surname']"),
  numberInput: document.querySelector("input[id='number']"),
  emailInput: document.querySelector("input[id='email']"),
};





const { nameInput, surnameInput, numberInput, emailInput } = inputs;

if (localStorage.length === 0) {
    containerElem.insertAdjacentHTML(
      "beforeend",
      `
        <p class="contacts-holder">You'll see your contacts here</p>
        `,
    );
}


if (localStorage.length > 0) {    
    for (let i = 0; i < localStorage.length; i++) {
        const contact = localStorage.key(i)
        const rootMain = JSON.parse(localStorage.getItem(contact));        


        contacts.insertAdjacentHTML(
          "beforeend",
          `
        <li data-root="${contact}" class="contacts-item">
                <div class="thumb">
                    <h3 class="name">${rootMain.nameInput} ${rootMain.surnameInput}</h3>
                    <a class="number" href="tel:${rootMain.numberInput}">${rootMain.numberInput}</a>
                </div>
                <div class="holder">
                    <a class="email" href="mailto: ${rootMain.emailInput}">${rootMain.emailInput}</a>
                    <button class="close-btn">X</button>
                </div>
            </li>
            `,
        );
    }    
}



form.addEventListener("submit", onFormSubmit)

function onFormSubmit(event) {
    event.preventDefault()

    localStorage.setItem(
      `${nameInput.value}-${surnameInput.value}`,
      JSON.stringify({
        nameInput: nameInput.value,
        surnameInput: surnameInput.value,
        numberInput: numberInput.value,
        emailInput: emailInput.value,
      }),
    );    

    

    const root = JSON.parse(localStorage.getItem(`${nameInput.value}-${surnameInput.value}`))
    
    
    contacts.insertAdjacentHTML(
      "beforeend",
      `
        <li data-root="${nameInput.value}-${surnameInput.value}" class="contacts-item">
                <div class="thumb">
                    <h3 class="name">${root.nameInput} ${root.surnameInput}</h3>
                    <a class="number" href="tel:${root.numberInput}">${root.numberInput}</a>
                </div>
                <div class="holder">
                    <a class="email" href="mailto: ${root.emailInput}">${root.emailInput}</a>
                    <button class="close-btn">X</button>
                </div>
            </li>
            `,
    );

    const contactsHolder = document.querySelector(".contacts-holder");

    nameInput.value = ""
    surnameInput.value = ""
    numberInput.value = ""
    emailInput.value = ""
    contactsHolder.style.display = 'none'

}






contacts.addEventListener("click", onCloseBtnClick)

function onCloseBtnClick(event) {
    const deleteBtn = event.target
    const contactsHolder = document.querySelector(".contacts-holder")
    if (deleteBtn.classList.contains("close-btn")) {
        const liItem = deleteBtn.parentNode.parentNode
        liItem.remove()
        localStorage.removeItem(liItem.dataset.root)

        if (contacts.children.length === 0) {
            contactsHolder.style.display = 'block';
        }
    }
}